from h import *

nueva('hypholoma-fasciculare', cient='Hypholoma fasciculare', sin=[], es=['hifoloma de láminas verdes'], eu=['suge-ziza mingots', 'suge-ziza mingotsa'], grupo='laminar', clase='toxica', cand=False,
  clave='Mata de setas amarillo azufre sobre madera, con láminas que pasan de amarillo a VERDE y sabor muy amargo. Un principiante la confunde con el hongo de miel. Tóxica.',
  mirar=[q('sombrero', 'Amarillo azufre, centro pardo-naranja', '2–8 cm; hemisférico, liso, amarillo azufre con el centro pardo-anaranjado y el borde blanquecino. A veces con restos de cortina pegados al borde.'),
         q('himenio', 'Láminas amarillas que verdean', 'Apretadas; al principio amarillas y luego de un verde característico, a medida que se forman las esporas negruzcas.'),
         q('esporada', 'Esporada pardo-púrpura', 'Pardo-púrpura (esporas negro-púrpura).'),
         q('pie', 'Amarillo claro, pardo-naranja abajo', '3–12 cm de alto y 3–10 mm de ancho; con una zona de anillo poco definida, oscurecida por las esporas.'),
         q('olor', 'Sabor muy amargo', 'El sabor es muy amargo.'),
         q('habitat', 'En mata sobre madera muerta', 'Madera muerta de frondosas y de coníferas, más a menudo de frondosas; sale en grupos.')],
  conf=[c('armillaria-mellea', 'Armillaria mellea (hongo de miel)', 'Wikipedia en español: se confunde fácilmente con los hongos de miel para el recolector principiante. La armilaria tiene láminas blancas y anillo ancho, sin tonos verdes.', 'alta'),
        c(None, 'Hypholoma capnoides', 'Comestible; no tiene las láminas verde-amarillentas ni el sabor amargo.', 'media'),
        c(None, 'Hypholoma sublateritium', 'Parecida, pero con el sombrero rojizo.', 'baja')],
  hab=['frondosas', 'coniferas', 'madera'], habt='Crece con abundancia sobre madera muerta de frondosas y coníferas; es más habitual en madera de frondosas en descomposición. Muy común en el norte de Europa y Norteamérica.',
  rec=dict(acc='dejar', txt='No se coge. Sale en mata sobre madera, justo donde se buscan setas de madera comestibles.'),
  sind='Retardado: diarrea, náuseas, vómitos, proteinuria y colapso; se han descrito parálisis y alteraciones de la vista. La toxicidad se atribuye en parte a los fasciculoles E y F.', lat='5–10 horas tras comerla', grav='La Wikipedia en euskera dice que ha causado intoxicaciones mortales',
  cur=['«fasciculare» viene del latín fascicularis, «en haces»: por cómo crece en matas.',
       'Los fasciculoles que se le atribuyen la toxicidad inhiben la calmodulina; en extractos se ha visto efecto anticoagulante.',
       'En inglés se llama «sulphur tuft» (mata de azufre) o «clustered woodlover».'],
  meses=[], mnota=None, wp=['hypholoma-fasciculare'], rioja=False)

nueva('scleroderma-citrinum', cient='Scleroderma citrinum', sin=['Scleroderma aurantium', 'Scleroderma vulgare'], es=[], eu=['astaputz arrunta', 'astaputz izarra'], grupo='bola', clase='toxica', cand=False,
  clave='Bola dura de corteza gruesa amarillo-ocre con verrugas, sin agujero arriba y con el interior oscuro enseguida. No es un bejín ni una trufa: es tóxica.',
  mirar=[q('sombrero', 'Corteza gruesa, ocre con verrugas', 'Hasta 10 cm de ancho y 6 de alto. El peridio (la piel) es grueso, firme y de ocre amarillo con verrugas irregulares. No tiene pie: se une al suelo por cordones de micelio.'),
         q('carne', 'Interior oscuro enseguida', 'La carne es mucho más firme que la de un bejín y su interior (gleba) se oscurece muy pronto, mientras que el bejín es blanco por dentro.'),
         q('otro', 'Sin agujero arriba', 'El bejín comestible tiene un único orificio arriba por el que salen las esporas; este solo se rompe para soltarlas.'),
         q('habitat', 'Bosques, brezales y césped corto', 'Ampliamente distribuida en bosques, brezales y césped corto de otoño a invierno.')],
  conf=[c('lycoperdon-perlatum', 'Bejines comestibles (Lycoperdon, Apioperdon)', 'Los bejines jóvenes son blancos y homogéneos por dentro y tienen un solo orificio arriba. Esta tiene la carne firme y oscura enseguida.', 'media'),
        c(None, 'Trufas', 'Wikipedia advierte de que los aficionados inexpertos la confunden con trufas.', 'alta')],
  hab=['bosque', 'brezal', 'prado'], habt='En bosques, brezales y césped corto, de otoño a invierno; es el «falso bejín» más común del Reino Unido. Es micorrícica: vive asociada a árboles.',
  rec=dict(acc='dejar', txt='No se coge. Tampoco para guisar: Wikipedia en euskera cuenta casos de fraude en restaurantes porque, sin la corteza, se parece a la trufa.'),
  sind='Molestias gastrointestinales en personas y animales. Las esporas pueden provocar lagrimeo, rinitis y conjuntivitis.', lat=None, grav=None,
  cur=['Puede estar parasitada por otro hongo, un boleto (Pseudoboletus parasiticus).',
       'Por su textura y aspecto se ha usado fraudulentamente en lugar de trufa.',
       'En inglés se llama «pigskin poison puffball» (bejín venenoso de piel de cerdo).'],
  meses=[9, 10, 11, 12], mnota='De otoño a invierno.', wp=['scleroderma-citrinum'], rioja=False)

nueva('russula-emetica', cient='Russula emetica', sin=['Agaricus emeticus'], es=['rúsula emética'], eu=['gibelgorri okagarri', 'gibelgorri okagarria'], grupo='laminar', clase='toxica', cand=False,
  clave='Rúsula de sombrero rojo escarlata o cereza, viscoso, que se pela casi hasta el centro; láminas y pie blancos y sabor MUY picante. Es la que hace vomitar: no se come.',
  mirar=[q('sombrero', 'Rojo escarlata o cereza, viscoso', '2,5–10 cm; convexo y luego aplanado, a veces hundido. En los maduros el borde tiene finas estrías. La cutícula se pela casi hasta el centro.'),
         q('himenio', 'Láminas blancas, apretadas', 'Blancas a crema, apretadas, unidas al pie o libres, a veces bifurcadas cerca del borde.'),
         q('pie', 'Blanco, liso y sin anillo', '4,5–10,5 cm de alto y 0,7–2,4 cm de ancho, seco y liso, relleno o algo hueco; sin anillo ni velo.'),
         q('carne', 'Quebradiza y muy picante', 'Blanca (rojiza justo bajo la cutícula) y quebradiza. Sabor muy picante.'),
         q('olor', 'Olor ligeramente afrutado o especiado', 'Un olor suave, algo afrutado o especiado.'),
         q('habitat', 'Con coníferas, entre esfagno', 'Micorrícica; prefiere coníferas, sobre todo pinos. Sola, dispersa o en grupos entre esfagno junto a turberas y en bosques de coníferas y mixtos.')],
  conf=[c('russula-cyanoxantha', 'Russula cyanoxantha (carbonera)', 'La carbonera nunca es roja y tiene las láminas flexibles y grasientas.', 'baja')],
  hab=['pinar', 'coniferas', 'mixto'], habt='Micorrícica con coníferas, sobre todo pinos. Brota entre esfagno cerca de turberas y en bosques de coníferas y mixtos; a veces sobre humus o madera muy podrida.',
  rec=dict(acc='dejar', txt='No se coge. No pruebes «un trocito» por probar: es muy picante y se desaconseja consumirla.'),
  sind='Náuseas, diarrea, vómitos y retortijones. Los síntomas empiezan entre media hora y tres horas después y suelen remitir solos. Wikipedia: no es tan peligrosa como se describía en guías antiguas.', lat='30 min a 3 h', grav='Digestiva; no suele ser grave según Wikipedia',
  cur=['Las ardillas rojas la buscan, la guardan y se la comen; están adaptadas a comer cosas ricas en terpenos, como los piñones.',
       'Se comió mucho en Europa del Este y en Rusia tras escaldarla y salarla o encurtirla. Aun así no se recomienda su consumo.',
       'En algunas zonas de Hungría y Eslovaquia se usa la cutícula del sombrero como especia en el gulash.',
       'Jacob Christian Schäffer la describió en 1774 como Agaricus emeticus.'],
  meses=[], mnota=None, wp=['russula-emetica'], rioja=False)

nueva('lactarius-torminosus', cient='Lactarius torminosus', sin=['Lactifluus torminosus'], es=['falso níscalo'], eu=['esnegorri faltsu', 'esnegorri faltsua', 'bora'], grupo='laminar', clase='toxica', cand=False,
  clave='Falso níscalo: sombrero rosa-anaranjado con círculos y el borde muy enrollado y lanoso, y látex BLANCO que no cambia de color y pica muchísimo. El níscalo bueno suelta látex naranja.',
  mirar=[q('sombrero', 'Rosa-anaranjado, borde lanoso y enrollado', '2–12 cm; hundido en forma de embudo poco profundo. El borde, fuertemente enrollado hacia dentro, está cubierto de pelos de joven; con círculos concéntricos más oscuros que se desdibujan. De rosa anaranjado a rosa pálido apagado.'),
         q('himenio', 'Láminas subdecurrentes', 'Bajan solo un poco por el pie.'),
         q('carne', 'Blanca y quebradiza', 'Blanca a color carne, firme y quebradiza; se vuelve blanda con la edad.'),
         q('olor', 'Látex blanco y muy picante', 'El látex, blanco a crema, no cambia de color con el aire ni mancha las láminas. Sabor acre muy picante, con olor de leve a fuerte.'),
         q('habitat', 'Bajo abedules', 'Micorrícica con abedul (y tsuga) en bosques mixtos; también en entornos urbanos si hay abedules cerca. Más probable en abedulares maduros.')],
  conf=[c('lactarius-deliciosus', 'Lactarius deliciosus (níscalo)', 'El níscalo suelta látex naranja-rojizo y verdea al manipularlo; el falso níscalo suelta látex blanco, picante, sin cambio de color. No son lo mismo.', 'alta')],
  hab=['abedular', 'mixto', 'parque'], habt='Micorrícica con abedul y tsuga en bosques mixtos; en zonas urbanas junto a abedules. Es una especie de climas templados norteños y boreales.',
  rec=dict(acc='dejar', txt='No se coge. En Finlandia y Rusia se prepara escaldándola, remojándola en salmuera varios días o encurtiéndola, pero cruda es tóxica y su sabor puede ampollar la lengua.'),
  sind='Síndrome resinoide: efecto purgante, náuseas y vómitos. Su sabor picante intenso en crudo puede ampollar la lengua si se prueba en exceso. No suele ser mortal.', lat=None, grav='Algunos autores la describen como causante de gastroenteritis leve a mortal',
  cur=['En Finlandia se recolecta para vender, tras escaldarla o ponerla en salmuera.',
       'Jacob Christian Schäffer la describió en 1774 como Agaricus.',
       'El compuesto al que se atribuye su toxicidad cruda es el velleral, de sabor picante.'],
  meses=[], mnota=None, wp=['lactarius-torminosus'], rioja=False)
